  check('encased in brick 457.2 / 914.4 / 2438.4 mm; 10 m3 needs 0.3281 m2 so 0.3 m2 fails; rectangular flue 0.12 m2 -> 0.48 m2 and 390 mm', [J(c0b + '.clr.map(c => Math.round(c.req * 10) / 10)'), R(J(c0b + '.rel'), 4), J(c0b + '.relOk'), R(J(c0b + '.fa'), 4), R(J(c0b + '.saA'), 4), R(J(c0b + '.saH'), 1)], [[457.2, 914.4, 2438.4], 0.3281, false, 0.12, 0.48, 390]);

