  // 400 x 300: equivalent round diameter sqrt(4 x 0.12 / pi) = 0.390882 m -> 391 mm
  check('400 x 300 mm: equivalent round diameter 391 mm and greater side 400 mm', [Math.round(J(ch('shape:1,a:400,b:300') + '.deq')), J(ch('shape:1,a:400,b:300') + '.dmax')], [391, 400]);
