  const c1 = ch('ns:4');
  check('interior metal chimney 400 mm: clearances 914.4 / 51 / 457.2 / 914.4 mm; termination 3.048 m within 7.62 m -> 13.048 m; 4 stories -> 2 h; breaching 12 gauge (2.49 mm) lined 63.5 mm', [J(c1 + '.clr.map(c => Math.round(c.req * 10) / 10)'), J(c1 + '.clr.map(c => c.mm)'), R(J(c1 + '.dh'), 3), R(J(c1 + '.rad'), 2), R(J(c1 + '.top'), 3), J(c1 + '.encl'), J(c1 + '.cga'), J(c1 + '.cgt'), J(c1 + '.clin')], [[914.4, 51, 457.2, 914.4], [914, 51, 457, 914], 3.048, 7.62, 13.048, 2, 12, 2.49, [63.5, 2.5]]);
