  const c1b = ch('kind:0,d:500,hot:1,hb:20,ns:3,cd:500');
  check('exterior metal chimney 500 mm, over 982 C: clearances 610 / 102 / 610 / 914.4 mm; 6.1 m within 15.24 m -> 26.1 m; 3 stories -> 1 h; gauge 10; breaching lined 114 mm (4 1/2 in.)', [J(c1b + '.clr.map(c => Math.round(c.req * 10) / 10)'), J(c1b + '.big'), R(J(c1b + '.dh'), 3), R(J(c1b + '.rad'), 2), R(J(c1b + '.top'), 3), J(c1b + '.encl'), J(c1b + '.ga'), J(c1b + '.clin')], [[610, 102, 610, 914.4], true, 6.1, 15.24, 26.1, 1, 10, [114, 4.5]]);
