  check('6.2.2.7.4 scope: linen chute at 200 and 1600 kg/m3 -> 16 gauge, not dense, no flag; limited-access waste chute at 200 kg/m3 -> 14 gauge with flag', [J(sq('use:2,rho:200') + '.waste'), J(sq('use:2,rho:200') + '.ga'), J(sq('use:2,rho:200') + '.dense'), J(sq('use:2,rho:200') + '.flag'), J(sq('use:2,rho:1600') + '.ga'), J(sq('use:1,rho:200') + '.ga'), J(sq('use:1,rho:200') + '.flag')], [false, 16, false, false, 16, 14, true]);
  // discharge room: 6.2.4.1.1 = chute enclosure rating (3 stories -> 1 h); chute feeding a compactor -> chute terminal / compacting room 2 h (8.2.4) with 1 1/2 h doors (8.2.4.1), page 5820
  check('chute discharge room: 3 stories without compactor -> 1 h, door rating not given as a number; with a compactor -> 2 h and 1 1/2 h doors (8.2.4 / 8.2.4.1); 6 stories with compactor -> 2 h / 1 1/2 h', [J(sq('') + '.comp'), J(sq('') + '.dencl'), J(sq('') + '.ddoor'), J(sq('comp:1') + '.comp'), J(sq('comp:1') + '.encl'), J(sq('comp:1') + '.dencl'), J(sq('comp:1') + '.ddoor'), J(c2.replace('ad:0.12', 'ad:0.12,comp:1') + '.dencl'), J(c2.replace('ad:0.12', 'ad:0.12,comp:1') + '.ddoor')], [false, 1, null, true, 1, 2, 1.5, 2, 1.5]);

  // ---- mode 3: pneumatic. 20 in. = 508 mm; 18 in. = 457.2 > 457; 16 in. = 406.4 > 406; height 1.5 x 508 = 762 mm; 11 gauge length 4 x 406 = 1.624 m; supports 3 ft = 0.9144 < 0.92 m
  const c3 = 'xndCalc({mode:3,sys:0,n:8,dr:508,od:457,dt:406,shr:0})';
  check('full pneumatic: riser 508 OK, outer door 457 < 457.2 fails, pipe 406 < 406.4 fails, opening height 762 mm, 11 gauge 1.624 m, supports 0.9144 m, 8 stories -> 2 h', [J(c3 + '.drMin'), J(c3 + '.drOk'), R(J(c3 + '.odMin'), 1), J(c3 + '.odOk'), R(J(c3 + '.dtMin'), 1), J(c3 + '.dtOk'), J(c3 + '.hmax'), R(J(c3 + '.l11'), 3), R(J(c3 + '.sup'), 4), J(c3 + '.encl')], [508, true, 457.2, false, 406.4, false, 762, 1.624, 0.9144, 2]);
