  const gp = (s) => 'xndCalc({mode:3,sys:1,n:3,dr:508,od:460,dt:450,shr:0,' + s + '})';
  check('gravity pneumatic: opening -> interface room 1 h (3 stories) / 2 h (8 stories); no opening -> no room; occupied/abutting -> sprinklers; otherwise not required', [J(gp('opn:1,occ:1') + '.ifc'), J(gp('opn:1,occ:1,n:8') + '.ifc'), J(gp('opn:0,occ:1') + '.ifc'), J(gp('opn:1,occ:1') + '.cdSpr'), J(gp('opn:1,occ:0') + '.cdSpr')], [1, 2, null, true, false]);
  check('door 460 and pipe 450 pass (11 gauge 1.8 m); a 300 mm pipe passes only with a shredder; 3 stories -> 1 h',[J('xndCalc({mode:3,sys:0,n:8,dr:508,od:460,dt:450,shr:0}).odOk'), J('xndCalc({mode:3,sys:0,n:8,dr:508,od:460,dt:450,shr:0}).dtOk'), R(J('xndCalc({mode:3,sys:0,n:8,dr:508,od:460,dt:450,shr:0}).l11'), 3), J('xndCalc({mode:3,sys:1,n:8,dr:508,od:460,dt:300,shr:1}).dtOk'), J('xndCalc({mode:3,sys:1,n:8,dr:508,od:460,dt:300,shr:0}).dtOk'), J('xndCalc({mode:3,sys:1,n:3,dr:508,od:460,dt:450,shr:0}).encl')], [true, true, 1.8, true, false, 1]);

