  check('incinerator room 2 h / 1 1/2 h, charging floor 2 h / 3 h, collector discharge room 2 h with no door rating', [[J(rm('room:0') + '.wall'), J(rm('room:0') + '.door'), J(rm('room:0') + '.need')], [J(rm('room:1') + '.wall'), J(rm('room:1') + '.door')], [J(rm('room:6') + '.wall'), J(rm('room:6') + '.door')]], [[2, 1.5, true], [2, 3], [2, null]]);
  // 6.3.6.1 / 6.4.4.1 print only a 2-hour wall toward the occupied part (pages 5819 / 5820)
  check('collector discharge room is a wall-only requirement; other rooms are not', [J(rm('room:6') + '.wallOnly'), J(rm('room:0') + '.wallOnly'), J(rm('room:3') + '.wallOnly')], [true, false, false]);
